import {BREAKOUT_BRICKS} from './breakout.mjs';
import {ARCADE_GAMES,ARCADE_LEVELS,arcadeScore} from './arcade.mjs';
export function arcadeBoard(c){const frame='<rect width="480" height="360" fill="#102c2c"/>';if(c.kind==='snake')return'<svg viewBox="0 0 480 360" role="img" aria-label="Alpen-Snake Spielfeld">'+frame+'<path d="M0 0H480V360H0Z" fill="none" stroke="#769d7e" stroke-width="3"/>'+c.snake.map((p,i)=>'<rect x="'+(p[0]*20+1)+'" y="'+(p[1]*20+1)+'" width="18" height="18" rx="3" fill="'+(i?'#7bb47f':'#e1db9e')+'"/>').join('')+'<circle cx="'+(c.food[0]*20+10)+'" cy="'+(c.food[1]*20+10)+'" r="7" fill="#c56a58"/>'+(c.countdown>0?'<text x="240" y="200" text-anchor="middle" font-size="64" fill="#fff1b8">'+Math.ceil(c.countdown)+'</text>':'')+'</svg>';
if(c.kind==='breakout')return '<svg viewBox="0 0 480 320" role="img" aria-label="Alpen-Breakout Spielfeld"><rect width="480" height="320" fill="#102c2c"/>'+BREAKOUT_BRICKS.map((b,i)=>c.bricks[i]?'<rect x="'+b.x+'" y="'+b.y+'" width="'+b.w+'" height="'+b.h+'" rx="3" fill="'+['#d9c58a','#b7c795','#8ab89f','#6b9d9b'][Math.floor(i/8)]+'"/>':'').join('')+'<rect x="'+(c.paddle-44)+'" y="294" width="88" height="10" rx="4" fill="#f1dfaa"/><circle cx="'+c.ball.x+'" cy="'+c.ball.y+'" r="5" fill="#fff1d1"/>'+(c.countdown>0?'<text x="240" y="200" text-anchor="middle" font-size="64" fill="#fff1b8">'+Math.ceil(c.countdown)+'</text>':'')+'</svg>';
return'<svg viewBox="0 0 480 320" role="img" aria-label="Pong Spielfeld"><rect width="480" height="320" fill="#102c2c"/><path d="M240 0V320" stroke="#72988c" stroke-width="2" stroke-dasharray="8 8"/><text x="200" y="45" text-anchor="middle" font-size="32" fill="#e6ddac">'+c.points+'</text><text x="280" y="45" text-anchor="middle" font-size="32" fill="#b5cfc2">'+c.against+'</text><rect x="18" y="'+(c.paddle-32)+'" width="10" height="64" rx="3" fill="#e6ddac"/><rect x="452" y="'+(c.opponent-32)+'" width="10" height="64" rx="3" fill="#93b8ac"/><circle cx="'+c.ball.x+'" cy="'+c.ball.y+'" r="6" fill="#f8efd1"/>'+(c.countdown>0?'<text x="240" y="190" text-anchor="middle" font-size="64" fill="#fff1b8">'+Math.ceil(c.countdown)+'</text>':'')+'</svg>';}
export const arcadeHeading=c=>ARCADE_GAMES[c.kind].name+' · '+ARCADE_LEVELS[c.level].name;
export const arcadeStats=c=>arcadeScore(c)+' Punkte · '+(c.kind==='snake'?c.eaten+' / 12 Beeren':c.kind==='breakout'?c.bricks.filter(v=>!v).length+' / 32 Steine · '+c.lives+' Bälle':c.points+' : '+c.against+' · zuerst 5')+' · '+Math.ceil(120-c.time)+' s';
